<script>document.addEventListener('click',function(e){const b=e.target.closest('.privacy-accordion [data-collapse]');if(!b)return;const root=b.closest('.privacy-accordion'),target=document.querySelector(b.dataset.collapse);root.querySelectorAll('.accordion-collapse').forEach(x=>{if(x!==target)x.classList.remove('show')});root.querySelectorAll('.accordion-button').forEach(x=>{if(x!==b)x.classList.add('collapsed')});target.classList.toggle('show');b.classList.toggle('collapsed',!target.classList.contains('show'));});</script>
